/* Project card styles for index page */
.project-list {
    display: grid;
    gap: 15px;
}

.project-card {
    background-color: #ffffff66;
    border-radius: 8px;
    padding: 20px;
    box-shadow: -7px -7px 10px #eeeeee44, 7px 7px 10px #00000011;
    border-left: #ffffff66 1px solid;
    border-top: #ffffff66 1px solid;
    border-bottom: #00000017 1px solid;
    border-right: #00000017 1px solid;
}

.project-card:hover {
    box-shadow: -10px -10px 15px #eeeeee66, 10px 10px 15px #00000022;
    transform: translateY(-1px);
    transition: all 0.2s ease;
}

.project-name {
    font-size: 1.2em;
    font-weight: 600;
    margin-bottom: 10px;
    word-break: break-all;
}

.project-name a {
    text-decoration: none;
    color: #2196f3;
}

.project-name a:hover {
    text-decoration: underline;
}

.project-stats {
    color: #666;
    font-size: 0.9em;
    display: flex;
    gap: 20px;
    flex-wrap: wrap;
}

.stat {
    display: flex;
    align-items: center;
    gap: 5px;
}

/* Summary section */
.summary {
    text-align: center;
    margin-bottom: 30px;
    padding: 15px;
    background-color: #ffffff66;
    border-radius: 8px;
    box-shadow: -7px -7px 10px #eeeeee44, 7px 7px 10px #00000011;
    border-left: #ffffff66 1px solid;
    border-top: #ffffff66 1px solid;
    border-bottom: #00000017 1px solid;
    border-right: #00000017 1px solid;
}

.summary-stats {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 15px;
}

.summary-stat {
    text-align: center;
}

.summary-stat .number {
    font-size: 1.5em;
    font-weight: 600;
    color: #2196f3;
}

.summary-stat .label {
    color: #666;
    font-size: 0.9em;
}

